# REF-Consistency-Build.ps1 - builds the "SANCTIR - Consistency Check" remediation (8 Oct 2026).
# Writes REF-Consistency-Detect.ps1 and -Remediate.ps1 next to this file from ONE core, which is also the hourly scanner.
#
# WHY. Standing requirement (Security Officer, 8 Oct 2026): silent failures must be found by the system, logged, and checked
# for consistency - not discovered by chance. On 7-8 Oct three went unseen: the Intune remediation scheduler stopped for
# 28 h after a restart (POAM-042); Defender's scheduled updates and scans stopped for 52 h (POAM-034 addendum); updated
# programs stayed blocked by stale firewall rules for hours. Each check below is aimed at one of those or at a control
# whose silent failure would matter as much.
#
# DESIGN. The scanner runs from its OWN scheduled task (SYSTEM, hourly and 10 minutes after startup), not through the Intune
# agent - so it still reports when the agent itself stalls. Every run writes to the SANCTIR event log (collected into
# Sentinel by dcr-REF-windows-security): event 3000 = run summary (the heartbeat), 3001 = a WARN check, 3002 = a FAIL
# check, each message 'CHECK=<id> <name> | STATUS=<s> | DETAIL=<text>'. Sentinel alerts on any 3002, and on any device that
# is online but has sent no 3000 for three hours (the scanner itself stopped). A JSON copy goes to
# C:\ProgramData\REF\Reports\consistency-latest.json. The scanner reads only; it changes nothing.
$ErrorActionPreference = 'Stop'
$here = Split-Path -Parent $MyInvocation.MyCommand.Path

$core = @'
# SANCTIR Consistency scanner v9 (12 Oct 2026; C03 judges the newest quick OR full scan, C06 ignores the boot-time push-channel event 4603; v8: C13 time source locked and peers; v7: C05 awake-aware, C24 local drift guards; v6: build stamp; v5: C23 update channels; v4: C19 tenant admin list).
# REF-BUILD: __STAMP__ Generated by REF-Consistency-Build.ps1 - do not edit by hand.
# READ-ONLY. -Log writes the results to the SANCTIR event log and the JSON report; without it, results are only returned.
param([switch]$Log)
$R = New-Object System.Collections.ArrayList
function Add-R($id, $name, $status, $detail) { [void]$R.Add([pscustomobject]@{ Check = $id; Name = $name; Status = $status; Detail = "$detail" }) }
function Try-Check($id, $name, [scriptblock]$sb) { try { & $sb } catch { Add-R $id $name 'WARN' "check could not run: $($_.Exception.Message)" } }
$now = Get-Date

Try-Check 'C01' 'Intune remediation scheduler' {
    $f = 'C:\ProgramData\Microsoft\IntuneManagementExtension\Logs\HealthScripts.log'
    $ime = Get-Service IntuneManagementExtension -ErrorAction SilentlyContinue
    if (-not $ime -or $ime.Status -ne 'Running') { Add-R 'C01' 'Intune remediation scheduler' 'FAIL' "IME service $($ime.Status)"; return }
    if (-not (Test-Path $f)) { Add-R 'C01' 'Intune remediation scheduler' 'FAIL' 'HealthScripts.log missing'; return }
    $det = @(Select-String -Path $f -Pattern 'pre-remdiation detection script compliance result for ([0-9a-f]{8})' | ForEach-Object { $id = $_.Matches[0].Groups[1].Value; if ($_.Line -match 'time="([0-9:]+)[^"]*" date="([0-9-]+)"') { [pscustomobject]@{ Id = $id; At = [datetime]::ParseExact("$($Matches[2]) $($Matches[1])", 'M-d-yyyy HH:mm:ss', $null) } } })
    $known = @($det.Id | Sort-Object -Unique).Count; $recent = @($det | Where-Object { $_.At -gt $now.AddHours(-2) } | ForEach-Object Id | Sort-Object -Unique).Count
    # Awake time, not uptime (9 Oct 2026: a 12-hour sleep produced a false FAIL - nothing scheduled runs while asleep).
    $boot = (Get-CimInstance Win32_OperatingSystem).LastBootUpTime; $wake = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-Power-Troubleshooter'; Id = 1 } -MaxEvents 1 -ErrorAction SilentlyContinue)[0].TimeCreated
    $up = ($now - $(if ($wake -and $wake -gt $boot) { $wake } else { $boot })).TotalHours
    if ($known -and $recent -lt [Math]::Ceiling($known / 2) -and $up -gt 2) { Add-R 'C01' 'Intune remediation scheduler' 'FAIL' "only $recent of $known remediations ran in the last 2 h (awake $([math]::Round($up, 1)) h)" }
    else { Add-R 'C01' 'Intune remediation scheduler' 'OK' "$recent of $known ran in the last 2 h" }
}
Try-Check 'C02' 'Defender protection and currency' {
    $m = Get-MpComputerStatus
    $bad = @(); if (-not $m.RealTimeProtectionEnabled) { $bad += 'real-time protection OFF' }; if (-not $m.IsTamperProtected) { $bad += 'tamper protection OFF' }; if ($m.AMRunningMode -ne 'Normal') { $bad += "mode $($m.AMRunningMode)" }
    if ($m.AntivirusSignatureAge -gt 2) { $bad += "signatures $($m.AntivirusSignatureAge) d old" }
    if ($bad) { Add-R 'C02' 'Defender protection and currency' 'FAIL' ($bad -join '; ') }
    elseif ($m.AntivirusSignatureAge -gt 1) { Add-R 'C02' 'Defender protection and currency' 'WARN' "signatures $($m.AntivirusSignatureAge) d old ($($m.AntivirusSignatureVersion))" }
    else { Add-R 'C02' 'Defender protection and currency' 'OK' "signatures $($m.AntivirusSignatureAge) d ($($m.AntivirusSignatureVersion))" }
}
Try-Check 'C03' 'Defender scheduled work' {
    $m = Get-MpComputerStatus; $ok = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Windows Defender/Operational'; Id = 2000; StartTime = $now.AddHours(-24) } -ErrorAction SilentlyContinue).Count
    $fail = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-Windows Defender/Operational'; Id = 2001; StartTime = $now.AddHours(-24) } -ErrorAction SilentlyContinue).Count
    # v9 (12 Oct 2026): the tenant schedules a daily FULL scan; judge the newest scan of either kind (quick-scan age alone
    # read 3 d while full scans ran daily - a false FAIL in the RA-027 audit)
    $scanAge = @(@($m.QuickScanAge, $m.FullScanAge) | Where-Object { $null -ne $_ -and $_ -ge 0 } | Measure-Object -Minimum).Minimum
    $d = "updates 24 h: $ok ok, $fail failed; newest scan $scanAge d (quick $($m.QuickScanAge) d, full $($m.FullScanAge) d)"
    if ($scanAge -gt 2 -or ($ok -eq 0 -and $m.AntivirusSignatureAge -gt 1)) { Add-R 'C03' 'Defender scheduled work' 'FAIL' $d } elseif ($ok -eq 0 -or $scanAge -gt 1 -or $fail -gt 3) { Add-R 'C03' 'Defender scheduled work' 'WARN' $d } else { Add-R 'C03' 'Defender scheduled work' 'OK' $d }
}
Try-Check 'C04' 'Windows Update' {
    $au = (New-Object -ComObject Microsoft.Update.AutoUpdate).Results; $s = $au.LastSearchSuccessDate
    $age = if ($s) { ($now.ToUniversalTime() - [datetime]$s).TotalHours } else { 999 }
    $pend = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired')
    $d = "last successful search $([int]$age) h ago; restart pending: $pend"
    if ($age -gt 30) { Add-R 'C04' 'Windows Update' 'FAIL' $d } else { Add-R 'C04' 'Windows Update' 'OK' $d }
}
Try-Check 'C05' 'Intune check-in (MDM)' {
    $acc = @(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Provisioning\OMADM\Accounts' -ErrorAction Stop)
    # v7: ServerLastSuccessTime is LOCAL time despite its Z suffix (verified 11 Oct 2026 against the sync events); no UTC conversion.
    $last = @(foreach ($a in $acc) { $v = (Get-ItemProperty (Join-Path $a.PSPath 'Protected\ConnInfo') -ErrorAction SilentlyContinue).ServerLastSuccessTime; if ($v) { try { [datetime]::ParseExact($v.Substring(0, 15), 'yyyyMMddTHHmmss', $null) } catch { } } }) | Sort-Object | Select-Object -Last 1
    # v7 (11 Oct 2026): awake-aware. After a 7-hour sleep the scan ran one minute after wake and read the pre-sleep timestamp,
    # seven minutes before the post-wake sync succeeded. A stale timestamp is a FAIL only once the device has been awake 1 h.
    $boot = (Get-CimInstance Win32_OperatingSystem).LastBootUpTime; $wake = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-Power-Troubleshooter'; Id = 1 } -MaxEvents 1 -ErrorAction SilentlyContinue)[0].TimeCreated
    $awake = ($now - $(if ($wake -and $wake -gt $boot) { $wake } else { $boot })).TotalHours
    if (-not $last) { Add-R 'C05' 'Intune check-in (MDM)' 'WARN' 'last successful check-in not readable' }
    elseif (($now - $last).TotalHours -gt 12 -and $awake -gt 1) { Add-R 'C05' 'Intune check-in (MDM)' 'FAIL' "last successful check-in $($last.ToString('MM-dd HH:mm')) (awake $([math]::Round($awake, 1)) h)" }
    elseif (($now - $last).TotalHours -gt 12) { Add-R 'C05' 'Intune check-in (MDM)' 'WARN' "last successful check-in $($last.ToString('MM-dd HH:mm')); awake $([math]::Round($awake * 60)) min, awaiting the post-wake sync" }
    else { Add-R 'C05' 'Intune check-in (MDM)' 'OK' "last successful check-in $($last.ToString('MM-dd HH:mm'))" }
}
Try-Check 'C06' 'Intune policy errors' {
    $e = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-DeviceManagement-Enterprise-Diagnostics-Provider/Admin'; Level = 2; StartTime = $now.AddHours(-24) } -ErrorAction SilentlyContinue | Where-Object { $_.Message -notmatch 'FakePolicy' -and $_.Message -notmatch 'push alert info for push initiated session' })   # v9: 4603 = WNS push channel not ready at boot, not a policy error
    $areas = @($e | ForEach-Object { if ($_.Message -match 'Area:\s*\(([^)]+)\)') { $Matches[1] } elseif ($_.Message -match 'CSP URI:\s*\(([^)]+)\)') { $Matches[1] -replace '^\./(Device|User)/Vendor/MSFT/', '' } else { "event $($_.Id)" } } | Group-Object | ForEach-Object { "$($_.Name) x$($_.Count)" })
    if ($e.Count) { Add-R 'C06' 'Intune policy errors' 'WARN' "$($e.Count) errors in 24 h: $($areas -join ', ')" } else { Add-R 'C06' 'Intune policy errors' 'OK' 'none in 24 h' }
}
Try-Check 'C07' 'Service baseline and watchdog' {
    $f = 'C:\ProgramData\REF\REF-Service-Baseline.ps1'
    if (-not (Test-Path $f)) { Add-R 'C07' 'Service baseline and watchdog' 'FAIL' 'watchdog file missing'; return }
    $need = @(& $f -Mode Check | Where-Object { $_ -like 'NEED *' })
    $t = Get-ScheduledTask -TaskName 'REF-Service-Watchdog' -ErrorAction SilentlyContinue
    if (-not $t -or "$($t.State)" -eq 'Disabled') { $need += 'watchdog task missing or disabled' }
    if ($need.Count) { Add-R 'C07' 'Service baseline and watchdog' 'FAIL' ($need -join '; ') } else { Add-R 'C07' 'Service baseline and watchdog' 'OK' 'baseline met, watchdog scheduled' }
}
Try-Check 'C08' 'Firewall versioned-path rules' {
    $f = 'C:\ProgramData\REF\REF-FW-VersionedPaths.ps1'
    if (-not (Test-Path $f)) { Add-R 'C08' 'Firewall versioned-path rules' 'FAIL' 'runner missing (FW-VersionedPaths v5 not applied)'; return }
    $need = @(& $f -Mode Check | Where-Object { $_ -like 'NEED *' })
    $t = Get-ScheduledTask -TaskName 'REF-FW-VersionedPaths' -ErrorAction SilentlyContinue
    if (-not $t -or "$($t.State)" -eq 'Disabled') { $need += 'runner task missing or disabled' }
    if ($need.Count) { Add-R 'C08' 'Firewall versioned-path rules' 'FAIL' ($need -join '; ') } else { Add-R 'C08' 'Firewall versioned-path rules' 'OK' 'all current, runner scheduled' }
}
Try-Check 'C09' 'Firewall profiles' {
    $bad = @(Get-NetFirewallProfile -PolicyStore ActiveStore | Where-Object { -not $_.Enabled -or $_.DefaultInboundAction -ne 'Block' -or $_.DefaultOutboundAction -ne 'Block' } | ForEach-Object { "$($_.Name): enabled=$($_.Enabled) in=$($_.DefaultInboundAction) out=$($_.DefaultOutboundAction)" })
    if ($bad) { Add-R 'C09' 'Firewall profiles' 'FAIL' ($bad -join '; ') } else { Add-R 'C09' 'Firewall profiles' 'OK' 'all profiles on, block in and out by default' }
}
Try-Check 'C10' 'Blocked-connection logging' {
    $v = @(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\PolicyManager\providers' -ErrorAction SilentlyContinue | ForEach-Object { (Get-ItemProperty (Join-Path $_.PSPath 'default\Device\Audit') -ErrorAction SilentlyContinue).ObjectAccess_AuditFilteringPlatformConnection } | Where-Object { $null -ne $_ })
    $n = try { @(Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 5157; StartTime = $now.AddHours(-24) } -MaxEvents 5 -ErrorAction Stop).Count } catch { -1 }
    if (-not @($v | Where-Object { $_ -ge 2 }).Count) { Add-R 'C10' 'Blocked-connection logging' 'FAIL' "audit setting not delivered (value: $($v -join ','))" }
    elseif ($n -eq 0) { Add-R 'C10' 'Blocked-connection logging' 'WARN' 'setting delivered but no 5157 event in 24 h' }
    else { Add-R 'C10' 'Blocked-connection logging' 'OK' "audit=failure; 5157 present: $(if ($n -lt 0) { 'unreadable from this account' } else { 'yes' })" }
}
Try-Check 'C11' 'Sentinel telemetry agents' {
    $bad = @(); foreach ($s in 'himds', 'GCArcService', 'ExtensionService') { $x = Get-Service $s -ErrorAction SilentlyContinue; if (-not $x -or $x.Status -ne 'Running') { $bad += "$s $($x.Status)" } }
    if (-not (Get-Process MonAgentCore -ErrorAction SilentlyContinue)) { $bad += 'Azure Monitor Agent (MonAgentCore) not running' }
    if ($bad) { Add-R 'C11' 'Sentinel telemetry agents' 'FAIL' ($bad -join '; ') } else { Add-R 'C11' 'Sentinel telemetry agents' 'OK' 'Arc and Azure Monitor Agent running' }
}
Try-Check 'C12' 'Cloudflare WARP' {
    $s = Get-Service CloudflareWARP -ErrorAction SilentlyContinue; $cli = 'C:\Program Files\Cloudflare\Cloudflare WARP\warp-cli.exe'
    $st = if (Test-Path $cli) { ((& $cli status 2>&1) -join ' ') -replace '\s+', ' ' } else { 'warp-cli missing' }
    if (-not $s -or $s.Status -ne 'Running') { Add-R 'C12' 'Cloudflare WARP' 'FAIL' "service $($s.Status)" } elseif ($st -notmatch 'Connected') { Add-R 'C12' 'Cloudflare WARP' 'WARN' $st } else { Add-R 'C12' 'Cloudflare WARP' 'OK' $st }
}
Try-Check 'C13' 'Time synchronisation' {
    # v8 (11 Oct 2026): the source must be USNO or NIST, the tenant's server list must be exactly in force, the clock must
    # have synced within 25 h (hourly polls; sleep allowed), and every configured peer must be reachable.
    $q = (& "$env:SystemRoot\System32\w32tm.exe" /query /status 2>&1) -join "`n"
    $want = 'tick.usno.navy.mil,0x9 tock.usno.navy.mil,0x9 ntp2.usno.navy.mil,0x9 time-a-g.nist.gov,0xb time-b-g.nist.gov,0xb'
    $pol = (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\W32Time\Parameters' -ErrorAction SilentlyContinue).NtpServer
    $bad = @(); $warn = @()
    if ("$pol" -ne $want) { $bad += "policy server list is '$pol'" }
    if ($q -match 'Source:\s*(.+)') { $src = $Matches[1].Trim(); if ($src -notmatch 'usno\.navy\.mil|nist\.gov') { $bad += "source '$src' is not USNO/NIST" } } else { $warn += 'source not readable' }
    if ($q -match 'Last Successful Sync Time:\s*(.+)') { $t = [datetime]$Matches[1].Trim(); $h = ($now - $t).TotalHours; if ($h -gt 25) { $bad += "last sync $([int]$h) h ago" } } else { $warn += 'last sync not readable' }
    $pv = (& "$env:SystemRoot\System32\w32tm.exe" /query /peers /verbose 2>&1) -join "`n"
    $peers = @([regex]::Matches($pv, 'Peer:\s*(\S+)[\s\S]*?Reachability:\s*(\d+)') | ForEach-Object { [pscustomobject]@{ Name = $_.Groups[1].Value; Reach = [int]$_.Groups[2].Value } })
    $unreach = @($peers | Where-Object { $_.Reach -eq 0 } | ForEach-Object Name)
    if ($peers.Count -lt 5) { $warn += "$($peers.Count) of 5 peers configured" }
    if ($unreach.Count -ge 3) { $bad += "unreachable peers: $($unreach -join ', ')" } elseif ($unreach.Count) { $warn += "unreachable: $($unreach -join ', ')" }
    $d = "source $src; last sync $([int]$h) h ago; peers reachable $($peers.Count - $unreach.Count)/$($peers.Count)"
    if ($bad) { Add-R 'C13' 'Time synchronisation' 'FAIL' (($bad + $warn) -join '; ') } elseif ($warn) { Add-R 'C13' 'Time synchronisation' 'WARN' (($warn -join '; ') + "; $d") } else { Add-R 'C13' 'Time synchronisation' 'OK' $d }
}
Try-Check 'C14' 'Disk encryption' {
    # 8 Oct 2026: the Shell property used first returns nothing under SYSTEM and produced a false FAIL. Order now: the
    # BitLocker cmdlet, then WMI, then the Shell property; an unreadable state is a WARN, never a FAIL.
    $st = $null; $how = ''
    try { $v = Get-BitLockerVolume -MountPoint 'C:' -ErrorAction Stop; $st = if ("$($v.ProtectionStatus)" -eq 'On') { 1 } else { 0 }; $how = "cmdlet: $($v.ProtectionStatus), $($v.VolumeStatus), $($v.EncryptionPercentage)%" } catch { }
    if ($null -eq $st) { try { $w = Get-CimInstance -Namespace root\cimv2\Security\MicrosoftVolumeEncryption -ClassName Win32_EncryptableVolume -Filter "DriveLetter='C:'" -ErrorAction Stop; $st = if ($w.ProtectionStatus -eq 1) { 1 } else { 0 }; $how = "WMI ProtectionStatus $($w.ProtectionStatus)" } catch { } }
    if ($null -eq $st) { $s = (New-Object -ComObject Shell.Application).NameSpace('C:').Self.ExtendedProperty('System.Volume.BitLockerProtection'); if ($s -eq 1) { $st = 1; $how = 'shell: on' } elseif ($s -eq 2) { $st = 0; $how = 'shell: off or suspended' } }
    if ($null -eq $st) { Add-R 'C14' 'Disk encryption' 'WARN' 'protection state not readable' }
    elseif ($st -ne 1) { Add-R 'C14' 'Disk encryption' 'FAIL' "BitLocker protection on C: is OFF or suspended ($how)" }
    else { Add-R 'C14' 'Disk encryption' 'OK' "BitLocker on ($how)" }
}
Try-Check 'C15' 'App Control and VBS' {
    $dg = Get-CimInstance -Namespace root\Microsoft\Windows\DeviceGuard -ClassName Win32_DeviceGuard
    $bad = @(); if ($dg.CodeIntegrityPolicyEnforcementStatus -ne 2) { $bad += "App Control enforcement $($dg.CodeIntegrityPolicyEnforcementStatus)" }; if ($dg.VirtualizationBasedSecurityStatus -ne 2) { $bad += "VBS $($dg.VirtualizationBasedSecurityStatus)" }; foreach ($svc in 1, 2) { if (@($dg.SecurityServicesRunning) -notcontains $svc) { $bad += @('', 'Credential Guard', 'memory integrity')[$svc] + ' not running' } }
    if ($bad) { Add-R 'C15' 'App Control and VBS' 'FAIL' ($bad -join '; ') } else { Add-R 'C15' 'App Control and VBS' 'OK' 'enforced; Credential Guard and memory integrity running' }
}
Try-Check 'C16' 'Removable-storage control' {
    $m = Get-MpComputerStatus; if ("$($m.DeviceControlState)" -ne 'Enabled') { Add-R 'C16' 'Removable-storage control' 'FAIL' "device control $($m.DeviceControlState)" } else { Add-R 'C16' 'Removable-storage control' 'OK' 'device control enabled' }
}
Try-Check 'C17' 'Event logging integrity' {
    $bad = @(); if ((Get-Service EventLog).Status -ne 'Running') { $bad += 'Event Log service not running' }
    $cleared = try { @(Get-WinEvent -FilterHashtable @{ LogName = 'Security'; Id = 1102; StartTime = $now.AddDays(-7) } -ErrorAction Stop).Count } catch { 0 }
    if ($cleared) { $bad += "Security log cleared $cleared time(s) in 7 days" }
    if ($bad) { Add-R 'C17' 'Event logging integrity' 'FAIL' ($bad -join '; ') } else { Add-R 'C17' 'Event logging integrity' 'OK' 'running; no log clear in 7 days' }
}
Try-Check 'C18' 'Local accounts' {
    $allowed = 'REF-la', 'CodexSandboxOffline', 'CodexSandboxOnline'
    $extra = @(Get-LocalUser | Where-Object { $_.Enabled -and $allowed -notcontains $_.Name } | ForEach-Object Name)
    if ($extra) { Add-R 'C18' 'Local accounts' 'FAIL' "unregistered enabled local account(s): $($extra -join ', ')" } else { Add-R 'C18' 'Local accounts' 'OK' 'only registered accounts enabled' }
}
Try-Check 'C19' 'Local Administrators' {
    # v4 (9 Oct): the expected members are read from the tenant's own LocalUsersAndGroups policy as delivered to this device,
    # so a member added in the tenant is expected and anything else fails. Fallback: the fixed list of 8 Oct.
    $members = @(([ADSI]"WinNT://./Administrators,group").psbase.Invoke('Members') | ForEach-Object { (New-Object Security.Principal.SecurityIdentifier(([ADSI]$_).objectSid.Value, 0)).Value })
    $xml = $null
    foreach ($k in @(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\PolicyManager\providers' -ErrorAction SilentlyContinue)) { $v = (Get-ItemProperty (Join-Path $k.PSPath 'default\Device\LocalUsersAndGroups') -ErrorAction SilentlyContinue).Configure; if ($v -match 'S-1-5-32-544') { $xml = $v } }
    $src = 'tenant policy'; $expected = @(); $unres = @()
    if ($xml) {
        $ag = @(([xml]$xml).GroupConfiguration.accessgroup | Where-Object desc -eq 'S-1-5-32-544')[0]
        foreach ($m in @($ag.add | ForEach-Object member)) {
            $lu = $null; if ($m -notmatch '^S-1-') { $lu = Get-LocalUser -Name $m -ErrorAction SilentlyContinue }
            if ($m -match '^S-1-') { $expected += $m } elseif ($lu) { $expected += $lu.SID.Value } else { try { $expected += (New-Object Security.Principal.NTAccount($m)).Translate([Security.Principal.SecurityIdentifier]).Value } catch { $unres += $m } }
        }
    } else {
        $src = 'fixed list (tenant policy not readable)'
        $expected = @((Get-LocalUser -Name 'REF-la' -ErrorAction SilentlyContinue).SID.Value, 'S-1-12-1-3298148996-1153151359-519037115-2679404937', 'S-1-12-1-638234756-1248851365-747764397-145304014') + @($members | Where-Object { $_ -match '-500$' })
    }
    $extra = @($members | Where-Object { $expected -notcontains $_ })
    $la = (Get-LocalUser -Name 'REF-la' -ErrorAction SilentlyContinue).SID.Value
    if ($extra) { Add-R 'C19' 'Local Administrators' 'FAIL' "member(s) not set by the tenant: $($extra -join ', ') (expected from $src)" }
    elseif (-not $la -or $members -notcontains $la) { Add-R 'C19' 'Local Administrators' 'WARN' 'break-glass REF-la is not in Administrators' }
    elseif ($unres -or -not $xml) { Add-R 'C19' 'Local Administrators' 'WARN' "$($members.Count) members, all expected; $src$(if ($unres) { "; unresolved policy names: $($unres -join ', ')" })" }
    else { Add-R 'C19' 'Local Administrators' 'OK' "$($members.Count) members, exactly as the tenant policy sets ($($expected.Count) listed)" }
}
Try-Check 'C20' 'Service crashes' {
    $c = @(Get-WinEvent -FilterHashtable @{ LogName = 'System'; ProviderName = 'Service Control Manager'; Id = 7031, 7034; StartTime = $now.AddHours(-24) } -ErrorAction SilentlyContinue | ForEach-Object { if ($_.Message -match '^The (.+?) service terminated') { $Matches[1] } } | Group-Object | ForEach-Object { "$($_.Name) x$($_.Count)" })
    if ($c) { Add-R 'C20' 'Service crashes' 'WARN' "24 h: $($c -join ', ')" } else { Add-R 'C20' 'Service crashes' 'OK' 'none in 24 h' }
}
Try-Check 'C21' 'App Control blocks' {
    $b = @(Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-CodeIntegrity/Operational'; Id = 3077; StartTime = $now.AddHours(-24) } -ErrorAction SilentlyContinue | ForEach-Object { if ($_.Message -match 'attempted to load (\S.*?) that') { Split-Path $Matches[1] -Leaf } } | Group-Object | ForEach-Object { "$($_.Name) x$($_.Count)" })
    if ($b) { Add-R 'C21' 'App Control blocks' 'WARN' "24 h: $($b -join ', ')" } else { Add-R 'C21' 'App Control blocks' 'OK' 'none in 24 h' }
}
Try-Check 'C22' 'Restart and disk' {
    $up = ($now - (Get-CimInstance Win32_OperatingSystem).LastBootUpTime).TotalDays; $free = (Get-PSDrive C).Free / ((Get-PSDrive C).Used + (Get-PSDrive C).Free)
    $pend = (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') -or (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending')
    $d = "up $([math]::Round($up, 1)) d; restart pending: $pend; C: free $([int]($free * 100)) %"
    if ($free -lt 0.10 -or ($pend -and $up -gt 3)) { Add-R 'C22' 'Restart and disk' 'WARN' $d } else { Add-R 'C22' 'Restart and disk' 'OK' $d }
}
Try-Check 'C23' 'Update channels not blocked' {
    # v5 (10 Oct 2026): Cloudflare Gateway now blocks cloud storage, unapproved AI and (from 17 Oct) new domains. This proves
    # hourly that no Gateway rule sinkholes an update or management channel. Resolved through WARP exactly as Windows does.
    # FAIL = Gateway answered 0.0.0.0/:: for a channel (a rule is blocking updates); WARN = no answer (usually the network).
    $hosts = 'update.microsoft.com', 'fe3.delivery.mp.microsoft.com', 'dl.delivery.mp.microsoft.com', 'download.windowsupdate.com', 'geo.prod.do.dsp.mp.microsoft.com',
        'definitionupdates.microsoft.com', 'wdcp.microsoft.com', 'unitedstates.x.cp.wd.microsoft.com', 'winatp-gw-cus.microsoft.com',
        'msedge.api.cdp.microsoft.com', 'msedge.b.tlu.dl.delivery.mp.microsoft.com', 'manage.microsoft.com', 'login.microsoftonline.com',
        'officecdn.microsoft.com', 'oneclient.sfx.ms', 'global.handler.control.monitor.azure.com', 'gbl.his.arc.azure.com', 'crl.microsoft.com',
        'downloads.cloudflareclient.com', 'downloads.dell.com'
    $blocked = @(); $noAns = @()
    foreach ($h in $hosts) {
        $ips = @(); foreach ($i in 1..2) { try { $ips = @(Resolve-DnsName $h -QuickTimeout -ErrorAction Stop | Where-Object { $_.IPAddress } | ForEach-Object IPAddress); break } catch { Start-Sleep -Milliseconds 500 } }
        if (-not $ips.Count) { $noAns += $h } elseif (-not @($ips | Where-Object { $_ -notin '0.0.0.0', '::' }).Count) { $blocked += $h }
    }
    if ($blocked) { Add-R 'C23' 'Update channels not blocked' 'FAIL' "BLOCKED by DNS filter: $($blocked -join ', ')" }
    elseif ($noAns.Count -ge 3) { Add-R 'C23' 'Update channels not blocked' 'WARN' "no DNS answer for $($noAns.Count) of $($hosts.Count): $($noAns -join ', ')" }
    else { Add-R 'C23' 'Update channels not blocked' 'OK' "$($hosts.Count - $noAns.Count) of $($hosts.Count) resolve, none blocked$(if ($noAns) { "; no answer: $($noAns -join ', ')" })" }
}
Try-Check 'C24' 'Local drift guards' {
    # v7 (11 Oct 2026): the event-triggered guards that make correction immediate must themselves be present, locked and armed.
    $bad = @()
    foreach ($g in @(@{ Task = 'REF-FW-Lockdown'; File = 'C:\ProgramData\REF\REF-FW-Lockdown.ps1'; Ev = '4946' }, @{ Task = 'REF-Policy-Guard'; File = 'C:\ProgramData\REF\REF-STIG-Guard.ps1'; Ev = '4657' }, @{ Task = 'REF-Service-Watchdog'; File = 'C:\ProgramData\REF\REF-Service-Baseline.ps1'; Ev = '7036' })) {
        if (-not (Test-Path -LiteralPath $g.File)) { $bad += "$($g.Task): file missing"; continue }
        $w = @((Get-Acl -LiteralPath $g.File).Access | Where-Object { $_.AccessControlType -eq 'Allow' -and "$($_.FileSystemRights)" -match 'Write|Modify|FullControl|ChangePermissions|TakeOwnership|Delete' -and "$($_.IdentityReference)" -notmatch '^(NT AUTHORITY\\SYSTEM|BUILTIN\\Administrators)$' })
        if ($w.Count) { $bad += "$($g.Task): file writable by a non-administrator" }
        $t = Get-ScheduledTask -TaskName $g.Task -ErrorAction SilentlyContinue
        if (-not $t) { $bad += "$($g.Task): task missing"; continue }
        if ("$($t.State)" -eq 'Disabled') { $bad += "$($g.Task): task disabled" }
        $ev = @($t.Triggers | Where-Object { $_.CimClass.CimClassName -eq 'MSFT_TaskEventTrigger' -and "$($_.Subscription)" -match $g.Ev })
        if (-not $ev.Count) { $bad += "$($g.Task): event trigger ($($g.Ev)) missing" }
    }
    if ($bad) { Add-R 'C24' 'Local drift guards' 'FAIL' ($bad -join '; ') } else { Add-R 'C24' 'Local drift guards' 'OK' 'firewall lockdown, policy guard and service watchdog present, locked and event-armed' }
}

$fail = @($R | Where-Object Status -eq 'FAIL'); $warn = @($R | Where-Object Status -eq 'WARN')
if ($Log) {
    $src = 'REF-Consistency'
    $sum = "SUMMARY | OK=$(@($R | Where-Object Status -eq 'OK').Count) | WARN=$($warn.Count) | FAIL=$($fail.Count) | checks=$($R.Count)" + $(if ($fail) { " | failed: $(($fail | ForEach-Object Check) -join ',')" } else { '' })
    try { Write-EventLog -LogName REF -Source $src -EventId 3000 -EntryType Information -Message $sum -ErrorAction Stop } catch { }
    foreach ($x in $warn) { try { Write-EventLog -LogName REF -Source $src -EventId 3001 -EntryType Warning -Message "CHECK=$($x.Check) $($x.Name) | STATUS=WARN | DETAIL=$($x.Detail)" -ErrorAction Stop } catch { } }
    foreach ($x in $fail) { try { Write-EventLog -LogName REF -Source $src -EventId 3002 -EntryType Error -Message "CHECK=$($x.Check) $($x.Name) | STATUS=FAIL | DETAIL=$($x.Detail)" -ErrorAction Stop } catch { } }
    try { New-Item -ItemType Directory -Force 'C:\ProgramData\REF\Reports' | Out-Null; [pscustomobject]@{ Computer = $env:COMPUTERNAME; At = $now.ToString('s'); Results = $R } | ConvertTo-Json -Depth 4 | Set-Content 'C:\ProgramData\REF\Reports\consistency-latest.json' -Encoding UTF8 } catch { }
}
$R
'@

# Build stamp (10 Oct 2026): never replace a NEWER installed scanner. On 9 Oct Intune's scheduler ran a cached v3 hours after
# an on-demand run installed v4, rolled the scanner back, and the old C19 raised false FAILs for admin.
$core = $core -replace '__STAMP__', (Get-Date -Format 'yyyyMMddHHmm')
$runnerPath = 'C:\ProgramData\REF\REF-Consistency.ps1'
$task = 'REF-Consistency-Scan'
$common = @'
$ErrorActionPreference = 'Continue'
$runnerPath = '__RUNNER__'; $taskName = '__TASK__'
$taskArgs = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "__RUNNER__" -Log'
function Norm($s) { ($s -replace "`r`n", "`n").Trim() }
function Stamp($s) { if ("$s" -match 'REF-BUILD:\s*(\d{12})') { [long]$Matches[1] } else { [long]0 } }
function Test-RunnerAcl($p) {
    $bad = @((Get-Acl -LiteralPath $p).Access | Where-Object { $_.AccessControlType -eq 'Allow' -and "$($_.FileSystemRights)" -match 'Write|Modify|FullControl|ChangePermissions|TakeOwnership|Delete' -and "$($_.IdentityReference)" -notmatch '^(NT AUTHORITY\\SYSTEM|BUILTIN\\Administrators)$' })
    $bad.Count -eq 0
}
function Test-Task {
    $t = Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
    if (-not $t) { return 'missing' }
    if ("$($t.State)" -eq 'Disabled') { return 'disabled' }
    if ("$($t.Principal.UserId)" -notmatch 'SYSTEM') { return "runs as $($t.Principal.UserId)" }
    if ("$($t.Actions[0].Arguments)" -ne $taskArgs) { return 'action changed' }
    if (-not @($t.Triggers | Where-Object { "$($_.Repetition.Interval)" -eq 'PT1H' }).Count) { return 'no hourly trigger' }
    if (-not @($t.Triggers | Where-Object { $_.CimClass.CimClassName -eq 'MSFT_TaskBootTrigger' }).Count) { return 'no startup trigger' }
    return 'ok'
}
'@ -replace '__RUNNER__', $runnerPath -replace '__TASK__', $task
$elev = @'
if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Output 'REFUSING TO RUN: must be elevated (Intune runs this as SYSTEM).'; exit 2 }
'@

$detect = @"
# REF-Consistency-Detect v1 (8 Oct 2026). Generated by REF-Consistency-Build.ps1 - do not edit by hand.
# Guards the scanner itself: exit 1 when the scanner file, its lock or its task is missing or altered, or when it has not
# written a run summary (SANCTIR event 3000) for more than 2 hours. The scan RESULTS go to Sentinel, not to this script.
$elev
$common
`$core = @'
$core
'@
`$need = @()
if (-not (Test-Path -LiteralPath `$runnerPath)) { `$need += 'scanner file missing' }
elseif ((Norm (Get-Content -LiteralPath `$runnerPath -Raw)) -ne (Norm `$core) -and (Stamp (Get-Content -LiteralPath `$runnerPath -Raw)) -le (Stamp `$core)) { `$need += 'scanner file differs from the tenant copy' }
elseif (-not (Test-RunnerAcl `$runnerPath)) { `$need += 'scanner file writable by a non-administrator' }
`$ts = Test-Task; if (`$ts -ne 'ok') { `$need += "scanner task: `$ts" }
`$last = Get-WinEvent -FilterHashtable @{ LogName = 'SANCTIR'; Id = 3000 } -MaxEvents 1 -ErrorAction SilentlyContinue
if (-not `$last -or `$last.TimeCreated -lt (Get-Date).AddHours(-2)) { `$need += "no scan summary since `$(if (`$last) { `$last.TimeCreated.ToString('MM-dd HH:mm') } else { 'ever' })" }
if (`$need.Count) { Write-Output (`$need -join '; '); exit 1 }
Write-Output "Consistency scanner present, locked and scheduled; last summary `$(`$last.TimeCreated.ToString('MM-dd HH:mm')): `$(`$last.Message)"
exit 0
"@

$remediate = @"
# REF-Consistency-Remediate v1 (8 Oct 2026). Generated by REF-Consistency-Build.ps1 - do not edit by hand.
# Installs the read-only consistency scanner: writes and locks the file, registers task ${task} (SYSTEM, hourly and 10
# minutes after startup), creates the event source, and runs one scan now so Sentinel has a result immediately.
$elev
$common
`$core = @'
$core
'@
`$log = @()
New-Item -ItemType Directory -Force -Path (Split-Path `$runnerPath) | Out-Null
if (-not (Test-Path -LiteralPath `$runnerPath)) { Set-Content -LiteralPath `$runnerPath -Value `$core -Encoding UTF8; `$log += 'scanner written' }
elseif ((Norm (Get-Content -LiteralPath `$runnerPath -Raw)) -ne (Norm `$core)) {
    if ((Stamp (Get-Content -LiteralPath `$runnerPath -Raw)) -gt (Stamp `$core)) { `$log += 'installed scanner is newer than this copy - kept (no downgrade)' }
    else { Set-Content -LiteralPath `$runnerPath -Value `$core -Encoding UTF8; `$log += 'scanner written' } }
if (-not (Test-RunnerAcl `$runnerPath)) { & "`$env:SystemRoot\System32\icacls.exe" `$runnerPath /inheritance:r /grant:r '*S-1-5-18:(F)' '*S-1-5-32-544:(F)' '*S-1-5-32-545:(RX)' | Out-Null; `$log += "scanner locked (icacls exit `$LASTEXITCODE)" }
try { if (-not [System.Diagnostics.EventLog]::SourceExists('REF-Consistency')) { New-EventLog -LogName REF -Source 'REF-Consistency' -ErrorAction Stop; `$log += 'event source created' } } catch { `$log += "event source: `$(`$_.Exception.Message)" }
`$ts = Test-Task
if (`$ts -ne 'ok') {
    `$a  = New-ScheduledTaskAction -Execute "`$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -Argument `$taskArgs
    `$t1 = New-ScheduledTaskTrigger -AtStartup; `$t1.Delay = 'PT10M'
    `$t2 = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(2) -RepetitionInterval (New-TimeSpan -Hours 1)
    `$p  = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    `$s  = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable -MultipleInstances IgnoreNew -ExecutionTimeLimit (New-TimeSpan -Minutes 10)
    Register-ScheduledTask -TaskName `$taskName -Description 'Sanctir: hourly read-only consistency scan of security, management and logging controls; results to the SANCTIR event log and Sentinel. Read C:\ProgramData\REF\REF-Consistency.ps1 for exactly what it checks.' -Action `$a -Trigger `$t1, `$t2 -Principal `$p -Settings `$s -Force | Out-Null
    `$log += "scanner task registered (was: `$ts)" }
`$res = @(& `$runnerPath -Log)
`$log += "scan: `$(@(`$res | Where-Object Status -eq 'OK').Count) ok, `$(@(`$res | Where-Object Status -eq 'WARN').Count) warn, `$(@(`$res | Where-Object Status -eq 'FAIL').Count) fail"
Write-Output (`$log -join '; ')
exit 0
"@

$enc = New-Object Text.UTF8Encoding($false)
[IO.File]::WriteAllText((Join-Path $here 'REF-Consistency-Detect.ps1'), $detect, $enc)
[IO.File]::WriteAllText((Join-Path $here 'REF-Consistency-Remediate.ps1'), $remediate, $enc)
[IO.File]::WriteAllText((Join-Path $here 'REF-Consistency-Core.ps1'), $core, $enc)   # for a manual read-only scan
foreach ($n in 'Detect', 'Remediate', 'Core') { $p = Join-Path $here "REF-Consistency-$n.ps1"; $e = $null; [void][System.Management.Automation.Language.Parser]::ParseFile($p, [ref]$null, [ref]$e); "{0,-10} {1} sha8 {2}" -f $n, $(if ($e) { "PARSE ERROR: $($e[0].Message) line $($e[0].Extent.StartLineNumber)" } else { 'parse OK' }), (Get-FileHash $p -Algorithm SHA256).Hash.Substring(0, 8) }
